 pixelEditor=createPixelEditor({root:$('pixelArtStudio'),getProject:()=>project,getBeatSeconds:()=>{const bar=map.bars.find(b=>map.secondsToTick(audio.currentTime)<b.endTick)||map.bars.at(-1);return map.tickToSeconds(Math.min(project.song.endTick,bar.tick+bar.beatTicks))-map.tickToSeconds(bar.tick);},onChange:mark,onProgram:(screen,beats)=>task(async()=>{if(!project.house)throw Error('Choose a house first.');const anchorId=$('path').value,bar=map.bars.find(b=>map.secondsToTick(audio.currentTime)<b.endTick)||map.bars.at(-1),existing=project.fixtures.filter(f=>f.matrix?.screenId===screen.id);if(existing.length!==0&&existing.length!==16)throw Error('This screen has missing rows. Undo the row removal before reprogramming it.');if(project.fixtures.length+(existing.length?0:16)>200||project.cues.length+16>2000)throw Error('Not enough fixture or cue space for this screen.');const fixtures=project.fixtures.map(f=>({...f})),rows=[];for(let row=0;row<16;row++){let f=existing.find(f=>f.matrix.row===row);if(f){f=fixtures.find(x=>x.id===f.id);f.anchorId=anchorId;}else{f=autoPatch(fixtures,{id:crypto.randomUUID(),name:screen.name+' · row '+(row+1),anchorId,profileId:'rgb-pixels',nodes:16,matrix:{screenId:screen.id,row,columns:16,rows:16}});fixtures.push(f);}rows.push(f);}const ids=new Set(rows.map(f=>f.id));const cues=project.cues.filter(c=>!(ids.has(c.fixtureId)&&c.effect==='pixel-screen'));for(const f of rows)cues.push(creativeCue({fixtureId:f.id,startTick:bar.tick,endTick:map.bars[Math.min(map.bars.length-1,bar.index+Number($('quickBars').value)-1)].endTick,effect:'pixel-screen',brightness:Number($('quickBrightness').value)/100}));screen.ticksPerFrame=Math.max(1,Math.round(beats*bar.beatTicks));project.version=3;project.fixtures=fixtures;project.cues=cues;selected=rows[0].id;fixtureUI();mark();notice('Screen mapped: 256 RGB pixels, 16 row fixtures, 768 DMX channels. Play My Show to see the animation.');})});
